prompt --application/shared_components/plugins/template_component/amc_next_bento
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(862201314917297909)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_BENTO'
,p_display_name=>'Next Bento'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<article class="amc-NBento-tile{if ?LINK_URL/} amc-NBento-tile--link{endif/} {case STATE/}{when success/}amc-NBento-tile--success{when warning/}amc-NBento-tile--warning{when danger/}amc-NBento-tile--danger{when info/}amc-NBento-tile--info{otherwise/}amc-NBento-tile--neutral{endcase/}">',
'  <span class="amc-NBento-fx" aria-hidden="true"></span>',
'  {if ?ICON/}<span class="amc-NBento-icon" aria-hidden="true"><span class="amc-NBento-glyph fa #ICON#"></span></span>{endif/}',
'  <div class="amc-NBento-body">',
'    {if ?EYEBROW/}<p class="amc-NBento-eyebrow">#EYEBROW#</p>{endif/}',
'    <h3 class="amc-NBento-title">{if ?LINK_URL/}<a class="amc-NBento-link" href="#LINK_URL#">#TITLE#</a>{else/}#TITLE#{endif/}</h3>',
'    {if ?DESCRIPTION/}<div class="amc-NBento-more"><p class="amc-NBento-desc">#DESCRIPTION#</p></div>{endif/}',
'  </div>',
'  {if ?VALUE/}<p class="amc-NBento-figure"><span class="amc-NBento-value">#VALUE#</span>{if ?VALUE_LABEL/} <span class="amc-NBento-valueLabel">#VALUE_LABEL#</span>{endif/}</p>{endif/}',
'  {if ?LINK_URL/}{if ?LINK_LABEL/}<span class="amc-NBento-cta" aria-hidden="true"><span class="amc-NBento-ctaText">#LINK_LABEL#</span><span class="amc-NBento-arrow fa fa-arrow-right"></span></span>{endif/}{endif/}',
'</article>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>false
,p_api_version=>1
,p_report_body_template=>'<div class="amc-NBento amc-NBento--#STYLE# {case ROW_HEIGHT/}{when compact/}amc-NBento--rowCompact{when tall/}amc-NBento--rowTall{otherwise/}amc-NBento--rowStandard{endcase/}"><ul class="amc-NBento-grid">#APEX$ROWS#</ul></div>'
,p_report_row_template=>'<li class="amc-NBento-item {case SPAN/}{when wide/}amc-NBento-item--wide{when tall/}amc-NBento-item--tall{when large/}amc-NBento-item--large{otherwise/}amc-NBento-item--normal{endcase/}{if HIGHLIGHT/} amc-NBento-item--featured{endif/}">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-bento.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-bento.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Each query row is one tile. Pick a Style, map Title (required) and any of Eyebrow, Description, Icon, Value, Value Label, State, Link URL, Link Label, Span and Featured. Span returns normal, wide, tall or large and builds the bento layout; the grid switches to two columns and then one column based on the width of the region itself, not the window. Featured returns Y for the tile the style should emphasise, such as the beam tile, the magazine cover story or the tile that is open first. Colors follow the active Universal Theme style, including dark styles, Theme Roller changes and right-to-left pages.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(659611470118821767)
,p_plugin_id=>wwv_flow_imp.id(862201314917297909)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'spotlightGlow'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Bento design, tagged with its Next direction. Spotlight Glow, motion: one light follows the pointer across the whole grid and lights the nearest borders. Beam Feature, motion: a light beam travels around the Featured tile, the others stay quiet. Tilt Tiles, depth: each tile tilts toward the pointer with its icon and figure floating above the surface. Layered Glass, depth: frosted tiles float at different heights over a soft blurred color field that shifts with the pointer. Neo Brutal, bold: ink borders, hard offset shadows and flat fills. Clay, bold: soft pillowy tiles with inner and outer shadows. Aurora Mosaic, bold: tiles cut as windows from one continuous aurora gradient with film grain. Grid Pattern, bold: grid and dot patterns with oversized outline icons. Magazine, smart: editorial cover story and numbered columns when wide, two columns when medium, a numbered contents list when narrow. Expanding Tiles, smart: the hovered or focused tile grows while its siblings shrink; a vertical accordion when narrow. The pointer effects need a mouse or trackpad and stop when the user prefers reduced motion; the static design stays complete.'
);
